import{z as s,x as A,o as l,c as p,q as t,j as i,D as E,d as r,s as n,S as o,b as e}from"./chunks/framework.C8m1ZpeB.js";const D=JSON.parse('{"title":"零售流与批发商","description":"","frontmatter":{"title":"零售流与批发商","date":"2026-09-08T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/retail-wholesaler.md","filePath":"quant/retail-wholesaler.md","lastUpdated":1791413859000}'),d={name:"quant/retail-wholesaler.md"};function m(u,a,h,f,c,F){const B=A("Mermaid");return l(),p("div",null,[a[2]||(a[2]=t('<h1 id="零售流与批发商" tabindex="-1">零售流与批发商 <a class="header-anchor" href="#零售流与批发商" aria-label="Permalink to &quot;零售流与批发商&quot;">​</a></h1><div class="epigraph"><p>把可立即成交的零售单从公开簿抽走、交给少数批发商内化，等于按客户类型分割市场。价差改善可以发生在客户层，公开深度与发现则取决于被抽走的流里有多少噪声、多少信息。</p><footer>—— Easley, Kiefer and O&#39;Hara, Cream-skimming or profit-sharing?, Journal of Finance, 1996；对照 Battalio, Journal of Finance, 1997</footer></div><p><a href="/quant/options-complex-orders">期权多腿</a>已经点到：零售结构常被批发商内化，股票市价单同样如此。缺口是场所层。美国可立即成交的零售流多数不进公开 <a href="/quant/lob-structure">LOB</a>，而由批发商对照全国最优内化，再打印到场外磁带。<a href="/quant/pfof-payment-flow">PFOF</a> 写的是引流契约；<a href="/quant/boehmer-retail-flow">零售流识别</a> 写的是统计痕迹。本课写批发商作为一类匹配场所：它如何筛选对手方、如何对照公开报价成交、以及公开簿因此少了什么。不重推 <a href="/quant/kyle-model">Kyle</a> 的单市场 \\(\\lambda\\)，也不把零佣金写成福利定理。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>公开连续簿把所有主动单混在同一条队列里，做市商用混合流的平均毒性定价，见 Glosten–Milgrom。批发商的生意是把零售可成交流单独拿出来：若这批流平均上较少与知情单对撞，内化的期望价差捕获可以高于在公开 BBO 上做市，一部分以价格改善还给客户、一部分以支付还给经纪商。Easley–Kiefer–O&#39;Hara 问的是奶油撇脂还是利润分享：抽走非知情流，会不会让留下的公开簿更毒、报价更宽。Battalio 则问第三市场是否只是成本竞争。问题不是「内化违法」，而是分割之后，客户有效价差、公开深度与价格发现三套指标会分叉。</p><p><span class="marginnote">奶油撇脂（cream-skimming）翻译成白话：像撇走牛奶最上层的那层奶油，只挑生意里最好做的客户——低风险的零售单——把剩下「难啃」的订单留给公开市场。争议在于：被挑走的恰是噪声单，公开簿里知情单占比上升，做市商只好加宽价差。好做的那部分被拿走后，没被挑走的交易反而更贵。</span></p><p>期权上同一逻辑更重：复杂单的筛选更难，批发商若只接「看起来像对冲」的腿，方向性结构仍可能漏到公开复杂簿。股票与期权不要混成一个系数。</p><h3 id="内化对照的是哪一个最优" tabindex="-1">内化对照的是哪一个最优 <a class="header-anchor" href="#内化对照的是哪一个最优" aria-label="Permalink to &quot;内化对照的是哪一个最优&quot;">​</a></h3><p>批发商通常承诺不劣于当时公开最优，并给出亚 tick 改善。对照物是保护报价拼出来的全国最优，不是本所队头。于是零售成交可以印在 NBBO 内部，而不在任何一张展示簿上减少队列。公开做市商看不见这批对手方，<a href="/quant/limit-vs-market-choice">限价对市价的选择</a> 在零售侧被经纪商代理掉了：客户以为自己在「市价」，实际对手是批发商的存货与对冲。</p><p><span class="marginnote">最佳执行义务约束的是经纪商对客户的平均质量，不是强制每笔都去公开竞价。Rule 605/606 让平均可被审计，单笔路径仍不透明。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>把流分成：零售可成交、机构主动、公开限价。质量分三张表。客户表：有效价差、实现价差、价格改善相对同期保护 NBBO。公开表：NBBO 宽度、近端深度、做市商实现价差。发现表：场外打印对中点后续移动的贡献，相对交易所主动腿。识别零售流用 BJZZ 一类痕迹，但制度一变痕迹会漂，必须与 606 路由份额交叉。</p><p><span class="marginnote">常见误区：只用一张表评内化好坏。客户表漂亮（价差改善）与公开表恶化（深度变薄）、发现表变差（价格发现变慢）完全可以同时成立。三套指标对应三方——零售客户、公开市场参与者、全体价格使用者——只报其中一张，等于替其中一方发言。</span></p><p>比较静态：若把同一批零售单强制送去公开簿，价差可能因噪声增加而窄，也可能因排队与费用而并不改善客户——两套结果都要报，不能只用「本应送去竞价」当反事实。不要把 <a href="/quant/kyle-model">Kyle</a> 的 \\(\\sigma_u\\) 直接加上零售量：内化后公开做市商看见的 \\(u\\) 已经变了。</p>',14)),(l(),i(o,null,{default:E(()=>[n(B,{id:"mermaid-40",class:"mermaid",graph:"flowchart%20LR%0A%20%20Retail%5B%22%E9%9B%B6%E5%94%AE%E5%8F%AF%E6%88%90%E4%BA%A4%E5%8D%95%22%5D%20--%3E%20WS%5B%22%E6%89%B9%E5%8F%91%E5%95%86%E5%86%85%E5%8C%96%22%5D%0A%20%20WS%20--%3E%20Imp%5B%22%E4%BA%9A%20tick%20%E6%94%B9%E5%96%84%20%2F%20TRF%20%E6%89%93%E5%8D%B0%22%5D%0A%20%20WS%20--%3E%20Hedge%5B%22%E5%AF%B9%E5%86%B2%E5%88%B0%E5%85%AC%E5%BC%80%E7%B0%BF%E6%88%96%E6%9C%9F%E8%B4%A7%22%5D%0A%20%20Retail%20--%3E%20Lit%5B%22%E8%8B%A5%E6%94%B9%E8%B5%B0%E5%85%AC%E5%BC%80%E7%B0%BF%3A%20%E5%99%AA%E5%A3%B0%E8%BF%9B%E6%B7%B7%E5%90%88%E6%B5%81%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[r("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,"批发商是知情筛选后的库存中介。筛选来自经纪商路由，不是来自公开身份披露。平均毒性低，则内化像低 \\(\\lambda\\) 的私下批量；一旦遇到知情零售或被机构伪装成零售，库存立刻要到公开市场对冲，毒性被转嫁给展示报价——与期权复杂成交后的对冲时钟同构。公开簿因此同时少了噪声掩护、多了批发商的对冲单。平静期价差仍可很窄（HFT 做市还在）；新闻期批发商更频繁地把单「吐回」交易所，公开深度在最需要噪声的时候更薄。",-1)),a[5]||(a[5]=e("p",null,[e("span",{class:"marginnote"},"给个数字感受价格改善：股价 10 美元、NBBO 卖价 10.01，批发商以 10.0095 成交，每股改善 0.05 美分；一笔 200 股的零售单改善约 10 美分。乘以每天数百万笔，这是批发商的生意底盘，也是 PFOF 谈判的筹码——「改善给客户」与「支付给经纪商」其实是同一块利润的两种分法。")],-1)),(l(),i(o,null,{default:E(()=>[n(B,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20TD%0A%20%20MIX%5B%22%E5%85%AC%E5%BC%80%E6%B7%B7%E5%90%88%E6%B5%81%3A%20%E9%9B%B6%E5%94%AE%20%2B%20%E6%9C%BA%E6%9E%84%20%2B%20%E7%9F%A5%E6%83%85%22%5D%20--%3E%20SKIM%5B%22%E6%89%B9%E5%8F%91%E5%95%86%E6%8A%BD%E8%B5%B0%E4%BD%8E%E6%AF%92%E9%9B%B6%E5%94%AE%E6%B5%81%22%5D%0A%20%20SKIM%20--%3E%20LEFT%5B%22%E5%85%AC%E5%BC%80%E7%B0%BF%E5%89%A9%E4%B8%8B%3A%20%E6%9C%BA%E6%9E%84%E4%B8%8E%E7%9F%A5%E6%83%85%E4%B8%BA%E4%B8%BB%22%5D%0A%20%20LEFT%20--%3E%20POISON%5B%22%E6%B7%B7%E5%90%88%E6%B5%81%E5%B9%B3%E5%9D%87%E6%AF%92%E6%80%A7%E4%B8%8A%E5%8D%87%22%5D%0A%20%20POISON%20--%3E%20WIDER%5B%22%E5%81%9A%E5%B8%82%E5%95%86%E5%8A%A0%E5%AE%BD%E6%8A%A5%E4%BB%B7%2C%20%E8%BF%91%E7%AB%AF%E6%B7%B1%E5%BA%A6%E5%8F%98%E8%96%84%22%5D%0A%20%20WIDER%20--%3E%20NEWS%5B%22%E6%96%B0%E9%97%BB%E6%9C%9F%E6%89%B9%E5%8F%91%E5%95%86%E6%8A%8A%E5%8D%95%E5%90%90%E5%9B%9E%E4%BA%A4%E6%98%93%E6%89%80%22%5D%0A%20%20NEWS%20--%3E%20THIN%5B%22%E6%9C%80%E9%9C%80%E8%A6%81%E5%99%AA%E5%A3%B0%E6%8E%A9%E6%8A%A4%E6%97%B6%2C%20%E5%85%AC%E5%BC%80%E6%B7%B1%E5%BA%A6%E6%9C%80%E8%96%84%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=t('<p>对执行：机构母单若与零售内化对撞，看不见对手；只能从 TRF 亚美分与成交后漂移推断场所质量。把零售内化当成「免费的暗池中点」，会忽略批发商有权择单、有权拒单。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>这是美国零售股票与期权的结构。欧洲、香港、内地的佣金与集中竞价不能用同一套批发商模型。批发商集中度高，经验系数跟着几家客户结构走。Meme 事件是压力样本，不是机制起源。下一课要问：内化所对照的「全国最优」本身由哪条规则拼出来——没有订单保护，改善二字没有法定锚。</p><p><span class="marginnote">不要用本课去设计如何把机构流伪装成零售。对象是市场分割，不是路由规避。</span></p><p>内化仍以公开保护报价为尺。下一课写这把尺的法律来源：没有订单保护，就没有可强制的全国最优，价格改善的分母会改。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>批发商按客户类型分割可成交流：客户可获价格改善，公开簿失去部分噪声掩护。</li><li>内化对照保护 NBBO，成交不必减少任何一张展示队列。</li><li>奶油撇脂与成本竞争可以并存，必须分客户、公开、发现三套指标。</li><li>出处：Easley, Kiefer and O&#39;Hara, <em>Journal of Finance</em>, 1996；Battalio, <em>Journal of Finance</em>, 1997；对照 SEC Rule 605/606 与 Harris 对内化的讨论。</li></ul>',7))])}const _=s(d,[["render",m]]);export{D as __pageData,_ as default};
